function Hash($p){try{(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}catch{Fail ("PDC_SUCCESSOR_HASH_READ_FAILED:" + [IO.Path]::GetFileName($p) + ":" + $_.Exception.Message)}}
