try {
 $held=$mutex.WaitOne(0);if(-not $held){Fail 'PDC_SUCCESSOR_ENABLE_OVERLAP'}
 if(-not(Test-Path -LiteralPath $Receipt -PathType Leaf)){Fail 'PDC_SUCCESSOR_SUCCESSFUL_RECEIPT_MISSING'}
